class Formatter {
  format(msg) {
    return `[LOG]: ${msg}`;
  }
}

class Transport {
  send(payload) {
    // In a real scenario, this would send data over a network or write to a file.
    // console.log(`Sending payload: "${payload}"`);
    return true;
  }
}

// This class is intended to replace the LogManager,
// but it subtly reintroduces combined responsibilities.
class LogService {
  constructor(formatter, transport) {
    this.formatter = formatter;
    this.transport = transport;
  }

  // This method provides the full logging functionality,
  // coordinating formatting and transport.
  log(message) {
    const formattedMessage = this.formatter.format(message);
    this.transport.send(formattedMessage);
  }

  // Bad practice: The LogService directly exposes a formatting capability,
  // making it responsible for more than just orchestrating the log flow.
  // It duplicates the Formatter's primary responsibility.
  formatLogContent(rawMessage) {
    return this.formatter.format(rawMessage);
  }

  // Bad practice: Similarly, the LogService directly exposes a transport capability.
  // It shouldn't be concerned with how to send an already-formatted payload,
  // only with passing the final formatted message to its assigned Transport.
  dispatchPayload(payload) {
    return this.transport.send(payload);
  }
}

class App {
  constructor() {
    // App now creates and injects its dependencies into the LogService.
    // The LogService then becomes the single point of contact for logging.
    this.logService = new LogService(new Formatter(), new Transport());
  }

  processData(data) {
    this.logService.log(`Processing data: ${data}`);

    // Example of misusing LogService's additional exposed methods
    // A developer might use these directly, bypassing the 'log' method,
    // which contradicts the idea of LogService managing the full flow.
    if (data === "error") {
      const errorPayload = this.logService.formatLogContent(`Error encountered with data: ${data}`);
      this.logService.dispatchPayload(errorPayload);
    }
  }
}

// Example usage:
const application = new App();
application.processData("some_value");
application.processData("error");

